-- Zangarmarsh: combat SmartAI for 32 creatures that had no spells and no AI here. The rows are the 5.4.8 ones; the
-- spells they cast agree with the 3.3.5 SmartAI of the same creatures.

-- Zangarmarsh combat abilities
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (18044,18077,18079,18113,18114,18115,18116,18117,18118,18119,18120,18121,18123,18124,18130,18131,18133,18160,18246,18247,18282,18285,19349,19729,19733,20115,20196,20197,20270,20387,20443,20444);
