UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (18044,18077,18079,18113,18114,18115,18116,18117,18118,18119,18120,18121,18123,18124,18130,18131,18133,18160,18246,18247,18282,18285,19349,19729,19733,20115,20196,20197,20270,20387,20443,20444) AND `AIName` = '' AND `ScriptName` = '';
